import {Table, RANKS, SUITS, STREETS, rank, suit, cardName, parseCards, handLabel, preflopScore, analyze, decide, evaluate, seeded, drawProbability} from './engine.js';
import {LESSONS, QUESTIONS, RANK_EXAMPLES} from './content.js';
import {DojoAudio} from './audio.js';
import {readBackup} from './backup.js';
import {dueQuestions,updateRecall,topicStats} from './learning.js';

const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), fmt=n=>Number(n||0).toLocaleString('ko-KR');
const KEY='holdem-dojo-v3', navs=[['game','♠','플레이'],['learn','▤','배우기'],['train','◎','훈련'],['review','↺','복기'],['growth','◇','성장']];
const actionKo={fold:'폴드',check:'체크',call:'콜',raise:'베팅 / 레이즈'},streetKo={preflop:'프리플랍',flop:'플랍',turn:'턴',river:'리버'};
const defaults=()=>({xp:0,hands:0,wins:0,lessons:[],answers:{},missed:[],history:[],daily:{},onboarded:false,settings:{sound:true,volume:35,hints:true,fourColor:true,speed:'normal',difficulty:'standard'},reviewed:[],reviewsCompleted:0,trophies:0});
let lab={pot:100,bet:50,outs:9,stage:'flop'};
let progress=defaults(),table=null,notes=[],screen='game',learnTab='path',lessonId=null,quizId=null,quizAnswer=null,quizSource=null,quizFilter='all',quizIndex=0,chartPos='BTN',chartSelection='AKs',reviewId=null,timer=null,toastTimer=null,coachCache=null,raiseOpen=false,raiseAmount=0,storageWarning=false,installPrompt=null,dialogReturn=null,pendingBackup=null;
const audio=new DojoAudio();
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved){progress={...defaults(),...saved.progress,settings:{...defaults().settings,...saved.progress?.settings}};if(saved.table){try{table=Table.restore(saved.table);notes=Array.isArray(saved.notes)?saved.notes:[];}catch{}}}else{const old=JSON.parse(localStorage.getItem('holdem_dojo_v8')||localStorage.getItem('holdem-dojo-4p-v1')||'null');if(old&&Number.isFinite(old.xp))progress.xp=Math.max(0,old.xp);}}catch{storageWarning=true;}
for(const key of ['lessons','missed','history','reviewed'])if(!Array.isArray(progress[key]))progress[key]=[];
progress.reviewsCompleted=Math.max(Number.isFinite(progress.reviewsCompleted)?progress.reviewsCompleted:0,progress.reviewed.length);
if(!progress.answers||typeof progress.answers!=='object')progress.answers={};if(!progress.daily||typeof progress.daily!=='object')progress.daily={};
for(const key of ['xp','hands','wins','trophies'])if(!Number.isFinite(progress[key])||progress[key]<0)progress[key]=0;
progress.settings.volume=Number.isFinite(progress.settings.volume)?Math.max(0,Math.min(100,progress.settings.volume)):35;
audio.configure(progress.settings.sound,progress.settings.volume);
const todayKey=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
function daily(){const key=todayKey();if(!progress.daily[key])progress.daily[key]={hands:0,questions:0,reviews:0,xp:0};return progress.daily[key];}
function save(){try{const keys=Object.keys(progress.daily).sort();for(const key of keys.slice(0,-60))delete progress.daily[key];localStorage.setItem(KEY,JSON.stringify({progress,table:table?.s,notes}));}catch{if(!storageWarning){storageWarning=true;toast('이 브라우저에서는 저장할 수 없습니다. 탭을 닫으면 이번 진행이 사라질 수 있어요.');}}}
function addXP(n){progress.xp+=n;daily().xp+=n;}
function belt(){const thresholds=[0,100,300,700,1400,2500,4500],names=['첫 걸음','화이트 벨트','옐로 벨트','그린 벨트','블루 벨트','브라운 벨트','블랙 벨트'];let i=thresholds.findLastIndex(v=>progress.xp>=v);return {name:names[i],level:i+1,next:thresholds[i+1]||null,pct:thresholds[i+1]?Math.min(100,(progress.xp-thresholds[i])/(thresholds[i+1]-thresholds[i])*100):100};}
function streak(){let n=0,d=new Date();for(let i=0;i<60;i++){const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const day=progress.daily[key];if(day&&(day.hands||day.questions||day.reviews))n++;else if(i>0)break;d.setDate(d.getDate()-1);}return n;}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function sound(kind){audio.configure(progress.settings.sound,progress.settings.volume);audio.play(kind);}
function card(c,{tiny=false,hidden=false,best=false}={}){if(c==null)return '<span class="playing-card empty" aria-hidden="true">♠</span>';const color=hidden?'':suit(c)===1?'red':suit(c)===2&&progress.settings.fourColor?'clubs':suit(c)===3?progress.settings.fourColor?'diamonds':'red':'';return `<span class="playing-card ${tiny?'tiny ':''}${hidden?'back':color}${best?' best':''}" ${hidden?'':`data-suit="${SUITS[suit(c)]}"`} role="img" aria-label="${hidden?'상대 비공개 카드':esc(cardName(c))}">${hidden?'♠':`<span class="rank">${RANKS[c%13]==='T'?'10':RANKS[c%13]}</span><span class="suit">${SUITS[suit(c)]}</span>`}</span>`;}
const cardsHTML=(cards,opts={})=>cards.map(c=>card(c,opts)).join('');
function navHTML(mobile=false){return navs.map(([id,icon,label])=>`<button class="${mobile?'':'nav-item '}${screen===id?'active':''}" data-nav="${id}" aria-label="${label}" ${screen===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span><span>${label}</span>${!mobile&&screen===id?'<i class="dot"></i>':''}</button>`).join('');}
function brand(){return '<div class="brand-symbol" aria-hidden="true">♠</div><div class="brand-copy"><div class="brand-name">홀덤 도장</div><small>THE HOLDEM DOJO</small></div>';}
function render(){
  const b=belt();$('app').innerHTML=`<div class="shell"><aside class="sidebar"><a href="#game" class="brand" data-nav="game">${brand()}</a><div class="nav-label">YOUR DAILY PRACTICE</div><nav class="nav-links" aria-label="주요 메뉴">${navHTML()}</nav><div class="sidebar-bottom"><div class="level-card"><div class="eyebrow gold">MY JOURNEY</div><strong>${b.name} <span class="muted small">Lv.${b.level}</span></strong><div class="progress-track"><span style="width:${b.pct}%"></span></div><span class="small muted">${fmt(progress.xp)} <span class="gold">XP</span>${b.next?' / '+fmt(b.next):''}</span></div><button class="text-button" data-do="settings">⚙ &nbsp; 게임 설정</button><button class="text-button" data-do="about">ⓘ &nbsp; 도장 이야기 · 제작자</button><div class="sidebar-foot">매일 조금씩, 더 좋은 판단.<br>가상 칩으로 자유롭게 연습하세요.</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><span>나의 도장</span><span>/</span><strong>${navs.find(n=>n[0]===screen)?.[2]}</strong></div><a href="#game" data-nav="game" class="brand mobile-brand">${brand()}</a><div class="top-actions"><span class="top-chip"><i class="online-dot"></i>나만의 AI 연습 테이블</span><button class="icon-button" data-do="sound" aria-label="${progress.settings.sound?'효과음 끄기':'효과음 켜기'}" title="효과음">${progress.settings.sound?'♪':'♩'}</button><button class="icon-button" data-do="settings" aria-label="게임 설정">⚙</button><button class="icon-button only-mobile" data-do="about" aria-label="제작자 정보">ⓘ</button><span class="avatar-you">나</span></div></header><main id="main" class="page" tabindex="-1">${screen==='game'?gameHTML():screen==='learn'?learnHTML():screen==='train'?trainHTML():screen==='review'?reviewHTML():growthHTML()}</main></div></div><nav class="mobile-nav" aria-label="주요 메뉴">${navHTML(true)}</nav>`;
}
function heading(label,title,copy,extra=''){return `<div class="page-heading"><div><div class="heading-label">${label}</div><h1>${title}</h1>${copy?`<p>${copy}</p>`:''}</div>${extra}</div>`;}
function coach(){const s=table.s;if(s.over||s.actor!==0)return null;const key=[s.handNumber,s.street,s.pot,s.currentBet,s.players.map(p=>p.folded+':'+p.stack).join(',')].join('|');if(coachCache?.key===key)return coachCache.value;const value=analyze(table.view(0),{rng:seeded(s.handNumber*771+s.pot+s.board.reduce((a,b)=>a+b,0))});coachCache={key,value};return value;}
function seatHTML(p){
  const s=table.s,pos=s.count===2?[[50,83],[50,15]]:s.count===4?[[50,83],[12,47],[50,15],[88,47]]:[[50,84],[12,65],[16,24],[50,15],[84,24],[88,65]], [x,y]=pos[p.id];
  const shown=p.id===0||(s.over&&s.result.showdown&&!p.folded);const best=s.over&&s.result.hands?.[p.id]?.cards||[];
  const hand=p.cards.map(c=>card(c,{tiny:p.id!==0,hidden:!shown,best:p.id===0&&best.includes(c)})).join('');
  return `<div class="seat ${x>70?'seat-right':x<30?'seat-left':''} ${p.id===0?'hero-seat':''} ${p.folded?'folded':''} ${p.out?'out':''} ${s.actor===p.id?'current':''}" style="left:${x}%;top:${y}%" aria-label="${p.name} ${p.out?'탈락':table.position(p.id)} 스택 ${p.stack}">${p.id===0?`<div class="hero-hand">${hand}</div>`:`<div class="mini-cards">${hand}</div><div class="seat-avatar ${p.color}" title="${p.label||''}">${p.avatar}${s.dealer===p.id?'<span class="dealer">D</span>':''}</div>`}<div class="seat-info"><div class="seat-name">${p.name}<span class="seat-position">${table.position(p.id)}</span>${p.id===0?`<span class="seat-stack num">${fmt(p.stack)}</span>`:''}</div>${p.id!==0?`<div class="seat-stack num">${fmt(p.stack)}</div>`:''}</div><div class="seat-action">${p.out?'탈락':s.over&&s.result.won[p.id]?`+${fmt(s.result.won[p.id])} 획득`:esc(p.last)}</div>${p.round&&!s.over?`<span class="seat-bet">◉ ${fmt(p.round)}</span>`:''}</div>`;
}
function gameHTML(){
  if(!table)return '';const s=table.s,p=s.players[0],legal=table.legal(0),advice=coach(),active=s.players.filter(p=>!p.out).length;
  const hint=progress.settings.hints&&s.mode==='practice',made=s.board.length>=3?evaluate([...p.cards,...s.board]):null;
  const status=s.over?(p.folded?'폴드 후 남은 플레이어의 승부가 끝났습니다.':'한 판 완료 · 판단을 돌아보고 다음 판으로.') : s.actor===0?`<strong>내 차례입니다.</strong> ${legal.call?`${fmt(legal.call)}을 더 내면 계속 참여합니다.`:'체크로 무료로 진행할 수 있습니다.'}`:s.actor>=0?`<span class="pulse"><i></i><i></i><i></i></span>${s.players[s.actor].name}의 차례`:'다음 공용 카드를 여는 중';
  return `${heading('PLAY. LEARN. GROW.','오늘도, 한 수 더.','한 판의 승리보다, 어제보다 나은 판단을 연습하세요.',`<span class="pill gold">◇ &nbsp; ${streak()||0}일의 꾸준함</span>`)}<div class="game-layout"><div class="game-main"><section class="table-card" aria-label="홀덤 테이블"><div class="table-toolbar"><div class="table-name">${s.mode==='tournament'?'도장 챔피언십':s.count===2?'헤즈업 스파링':'코치 연습실'}<small>${active}인 · ${s.sb}/${s.bb}</small></div><div class="table-tools"><span class="pill">#${String(s.handNumber).padStart(3,'0')}</span><button data-do="modes">테이블 변경</button><button data-do="guide">?</button></div></div><div class="table-stage" data-testid="table"><div class="felt"></div><div class="board-area"><div class="street-steps">${STREETS.map(st=>`<span class="${s.street===st?'active':''}">${st==='preflop'?'PRE':st.toUpperCase()}</span>`).join('')}</div><div class="pot-label">${s.over?'FINAL POT':'TOTAL POT'}</div><div class="pot-value num">${fmt(s.over?s.result.totalPot:s.pot)}<small>${((s.over?s.result.totalPot:s.pot)/s.bb).toFixed(1)} BB</small></div><div class="board-cards">${Array.from({length:5},(_,i)=>card(s.board[i])).join('')}</div><div class="board-brand">THE HOLDEM DOJO</div></div>${s.players.map(seatHTML).join('')}${s.over&&s.result.net[0]>0?'<div class="result-celebration"></div>':''}</div><div class="table-status" role="status" aria-live="polite">${status}</div></section>${s.over?resultHTML():`<section class="action-panel" aria-label="내 행동"><div class="action-head"><strong>${made?made.name:handLabel(p.cards)} <span class="muted small">· ${table.position(0)}</span></strong><span>내 스택 <span class="gold">${(p.stack/s.bb).toFixed(1)} BB</span></span></div>${hint&&advice?`<button class="mobile-coach-tip" data-do="coach-detail">✧ 코치 · ${actionKo[advice.suggested]} 검토 <span style="float:right">이유 보기 ↗</span></button>`:''}<div class="action-buttons"><button class="action-button" data-action="fold" ${!legal.actions.includes('fold')?'disabled':''}>폴드<small>이번 판 내려놓기</small></button><button class="action-button call" data-action="${legal.call?'call':'check'}" ${!legal.actions.length?'disabled':''}>${legal.call?'콜':'체크'}<small>${legal.call?fmt(legal.call)+' 추가':'추가 비용 없음'}</small></button><button class="action-button raise" data-do="raise" ${!legal.canRaise?'disabled':''}>${raiseOpen?'크기 선택 중':s.currentBet?'레이즈':'베팅'}<small>${legal.canRaise?'내가 크기 정하기':'지금은 불가능'}</small></button></div><div class="raise-controls" ${!raiseOpen?'hidden':''}><div class="raise-row"><label for="raise-range" class="small muted">이번 라운드 총액</label><input type="range" id="raise-range" aria-label="레이즈 총액" min="${Math.min(legal.minRaise||20,legal.maxRaise||20)}" max="${legal.maxRaise||20}" step="1" value="${raiseAmount}"><input type="number" id="raise-number" aria-label="레이즈 총액 직접 입력" min="${Math.min(legal.minRaise||20,legal.maxRaise||20)}" max="${legal.maxRaise||20}" value="${raiseAmount}"></div><div class="presets"><button data-size=".33">⅓ 팟</button><button data-size=".5">½ 팟</button><button data-size=".75">¾ 팟</button><button data-size="all">올인</button></div><button class="button primary wide" style="margin-top:10px" data-do="confirm-raise">총 ${fmt(raiseAmount)}으로 확정</button><p class="small muted" style="margin-top:8px">표시는 추가액이 아닌 이번 라운드의 총 베팅액입니다.</p></div><div class="shortcut-note">단축키 F 폴드 · C 체크/콜 · R 레이즈 · Enter 확정</div></section>`}<div class="table-footer"><span>◉ 가상 칩 · 현금 가치 없음</span><button class="text-button" style="padding:0;font-size:inherit" data-do="log">핸드 기록 보기 ↗</button></div></div><aside class="game-aside"><section class="info-card coach-card"><div class="card-top"><h3>✧ &nbsp; 나의 코치</h3><span class="coach-badge">${hint?'COACH ON':'FOCUS MODE'}</span></div>${coachHTML(advice,hint)}</section>${missionsHTML()}${nextLessonHTML()}</aside></div>`;
}
function coachHTML(advice,hint){const s=table.s;if(!hint)return `<div class="coach-headline">판단은 나의 몫.</div><p class="coach-copy">실전처럼 힌트 없이 플레이합니다. 판이 끝나면 당시의 선택과 설명을 복기할 수 있어요.</p><div class="coach-foot">연습실에서 코치 힌트를 켤 수 있습니다.</div>`;if(s.over)return `<div class="coach-headline">결과보다, 이유.</div><p class="coach-copy">${notes.length?esc(notes[notes.length-1].advice.why):'상대가 모두 폴드한 판도, 내가 내려놓은 판도 배움이 됩니다. 카드와 행동 순서를 함께 돌아보세요.'}</p><div class="coach-foot">복기는 당시 정보 기준 · 승패로 정답을 판단하지 않습니다.</div>`;if(!advice)return '<div class="coach-headline">상대를 관찰하세요.</div><p class="coach-copy">누가 먼저 들어오고, 얼마나 베팅하는지 봅니다. 내 차례가 오면 지금 상황에 맞는 힌트를 드릴게요.</p><div class="coach-foot">AI는 자기 카드와 공개된 정보만 사용합니다.</div>';return `<span class="pill gold">생각해 볼 선택</span><div class="coach-headline">${actionKo[advice.suggested]}</div><p class="coach-copy">${esc(advice.why)}</p>${advice.equity!==null?`<div class="metric-pair"><div><span>무작위 상대 기준 지분</span><b class="gold num">~${Math.round(advice.equity*100)}<small>%</small></b></div><div><span>콜에 필요한 팟 지분</span><b class="num">${Math.round(advice.odds*100)}<small>%</small></b></div></div>`:''}${advice.draws.cards.length?`<p class="small muted" style="margin-top:12px">드로우 완성 후보 ${advice.draws.cards.length}장 · 모두 승리를 보장하는 아웃은 아닙니다.</p>`:''}<div class="coach-foot">학습용 근사 · 상대의 베팅 범위를 반영한 GTO 분석이 아닙니다.</div>`;}
function missionsHTML(){const d=daily(),rows=[['집중해서 3판',d.hands,3,'플레이'],['훈련 문제 3개',d.questions,3,'훈련'],['한 판 돌아보기',d.reviews,1,'복기']];return `<section class="info-card mission-card"><div class="card-top"><h3>오늘의 루틴</h3><span class="small muted">${rows.filter(r=>r[1]>=r[2]).length}/3</span></div>${rows.map(([title,n,total,tag])=>`<div class="mission-row"><span class="mission-check ${n>=total?'done':''}">${n>=total?'✓':'·'}</span><div class="mission-text"><strong>${title}</strong><small>${Math.min(n,total)} / ${total}</small></div><span class="mission-xp">${tag}</span></div>`).join('')}</section>`;}
function nextLessonHTML(){const lesson=LESSONS.find(l=>!progress.lessons.includes(l.id))||LESSONS[0];return `<section class="info-card continue-card"><div class="card-top"><h3>다음 한 수</h3><span class="small gold">${lesson.minutes} MIN</span></div><div class="mini-lesson-art"><span class="lesson-symbol">${lesson.icon}</span><span class="eyebrow muted">${lesson.tag}</span></div><div class="next-lesson"><strong>${lesson.title}</strong>${lesson.summary}</div><button class="text-button gold" data-lesson="${lesson.id}" style="margin-top:8px">이어서 배우기 &nbsp; →</button></section>`;}
function resultHTML(){const s=table.s,r=s.result,p=s.players[0],win=r.net[0]>0,champ=s.mode==='tournament'&&s.players.filter(p=>p.stack>0).length===1&&p.stack>0,bust=s.mode==='tournament'&&p.stack<=0;return `<section class="review-banner" aria-live="polite"><h3>${champ?'도장 챔피언이 되었습니다!':bust?'좋은 도전이었습니다.':win?'좋은 한 판이었습니다.':p.folded?'기다림도 실력입니다.':r.net[0]===0?'팟을 나누었습니다.':'다음 한 수를 준비해요.'} <span class="num ${r.net[0]>=0?'positive':'negative'}">${r.net[0]>0?'+':''}${fmt(r.net[0])}</span></h3><p>${r.showdown?'쇼다운':'상대 폴드'} · 총 팟 ${fmt(r.totalPot)} · 내 획득 ${fmt(r.won[0])} · 완료 보상 +10 XP${r.pots.length>1?' · 팟별 분배는 복기에서 확인':''}</p><div class="inline-actions"><button class="button ghost" data-review="${s.handId}">이 판 복기</button><button class="button primary" data-do="${champ||bust?'new-tournament':'next'}">${champ||bust?'새 챔피언십':'다음 핸드'} &nbsp; →</button></div></section>`;}
function learnHTML(){
  if(lessonId){const lesson=LESSONS.find(l=>l.id===lessonId);return `<div class="reading"><button class="text-button" data-do="back-lessons">← 학습 과정으로</button><div class="lesson-progress">${LESSONS.map(l=>`<i class="${progress.lessons.includes(l.id)?'done':''}"></i>`).join('')}</div>${heading(`LESSON ${lesson.icon} · ${lesson.minutes} MIN`,lesson.title,lesson.tag)}<p class="reading-intro">${lesson.summary}</p>${lesson.body.map(([title,text])=>`<section class="reading-block"><h3>${title}</h3><p>${text}</p></section>`).join('')}<div class="feedback"><strong>알았다면, 한 문제로 확인.</strong>직접 답해 보면 더 오래 기억에 남습니다.</div><button class="button primary wide" style="margin-top:17px" data-lesson-quiz="${lesson.id}">${progress.lessons.includes(lesson.id)?'다시 확인하기':'확인 문제 풀기'} →</button></div>`;}
  return `${heading('LEARN THE GAME','아는 만큼, 보이는 게임.','기초부터 실전 판단까지. 하루 한 수씩 익혀보세요.',`<span class="pill gold">${progress.lessons.length} / 10 완료</span>`)}<div class="content-tabs">${[['path','학습 과정'],['ranks','족보 한눈에'],['chart','핸드차트'],['lab','팟 오즈 실험실']].map(([id,label])=>`<button class="tab ${learnTab===id?'active':''}" data-learn-tab="${id}">${label}</button>`).join('')}</div>${learnTab==='path'?`<div class="content-grid">${LESSONS.map(l=>`<button class="lesson-card" data-lesson="${l.id}"><span class="lesson-index">${l.icon}</span><div><small>${l.tag} · ${l.minutes}분</small><h3>${l.title}</h3><p>${l.summary}</p></div>${progress.lessons.includes(l.id)?'<span class="lesson-done">✓</span>':''}</button>`).join('')}</div>`:learnTab==='ranks'?`<div class="ranks-list">${RANK_EXAMPLES.map(([name,cards,text],i)=>`<div class="rank-item"><span class="rank-number">${String(i+1).padStart(2,'0')}</span><div class="rank-copy"><h3>${name}</h3><p>${text}</p></div><div class="card-row">${cardsHTML(parseCards(cards))}</div></div>`).join('')}</div>`:learnTab==='lab'?labHTML():chartHTML()}`;
}
function labHTML(){return `<div class="reading"><div class="welcome-callout"><div><strong>콜의 가격을 직접 바꿔보세요.</strong><p>같은 카드라도 상대의 베팅 크기에 따라 필요한 지분은 달라집니다.</p></div></div><section class="info-card">${[['pot','상대가 베팅하기 전 팟',2000,10],['bet','상대의 베팅 = 내 콜 비용',2000,10],['outs','드로우 완성 후보 카드',20,1]].map(([id,label,max,step])=>`<label class="lab-input"><span>${label}<output id="lab-${id}-value">${fmt(lab[id])}</output></span><input type="range" min="0" max="${max}" step="${step}" value="${lab[id]}" data-lab="${id}" aria-label="${label}"></label>`).join('')}<div class="form-row"><div><strong>현재 단계</strong><small>카드가 몇 장 더 남아 있나요?</small></div><select data-lab="stage" aria-label="확률 실험 단계"><option value="flop" ${lab.stage==='flop'?'selected':''}>플랍 · 2장 남음</option><option value="turn" ${lab.stage==='turn'?'selected':''}>턴 · 1장 남음</option><option value="river" ${lab.stage==='river'?'selected':''}>리버 · 0장 남음</option></select></div></section><div class="lab-results">${labResultHTML()}</div><p class="small muted" style="line-height:1.9;margin-top:17px">헤즈업, 사이드팟·수수료 없음, 아웃 수가 다음 카드에서 변하지 않는 단순 모델입니다. 완성 확률은 승률이 아닙니다. 더 높은 패에 지는 더티 아웃과 앞으로의 베팅 비용을 함께 고려하세요.</p></div>`;}
function labResultHTML(){const total=lab.pot+2*lab.bet,odds=total?lab.bet/total:0,unseen=lab.stage==='flop'?47:46,remaining=lab.stage==='flop'?2:lab.stage==='turn'?1:0,one=drawProbability(lab.outs,unseen,Math.min(1,remaining)),all=drawProbability(lab.outs,unseen,remaining);return `<div class="lab-metrics">${[['콜에 필요한 지분',odds,'gold'],['다음 한 장으로 완성',one,'mint'],['리버까지 무료로 보면',all,'mint']].map(([label,n,color])=>`<div><div class="probability-ring" style="--percent:${n*100}%;--ring-color:var(--${color})"><b>${(n*100).toFixed(1)}<small>%</small></b></div><span>${label}</span></div>`).join('')}</div><div class="feedback"><strong>${lab.bet===0?'체크에는 추가 비용이 없습니다.':`${fmt(lab.bet)} ÷ ${fmt(total)} = ${(odds*100).toFixed(1)}%`}</strong>${lab.stage==='river'?'리버 이후에는 카드가 없습니다. 드로우 기대를 빼고 지금 패와 상대 범위를 비교하세요.':remaining===2?'두 장을 보는 확률이 좋아 보여도, 이번 콜로 리버까지 무료로 볼 수 있는지는 별개입니다. 턴에서 다시 베팅을 맞을 수 있습니다.':'턴에서는 카드가 한 장만 남습니다. 지금 가격과 실제로 이기는 아웃을 함께 따져보세요.'}</div>`;}
function chartTier(a,b){const score=preflopScore([a,b]);return score>83?'strong':score>=(chartPos==='BTN'?53:chartPos==='CO'?57:chartPos==='SB'?60:63)?'play':'';}
function chartHTML(){const labels=[...RANKS].reverse();return `<div class="reading"><p class="muted small">4인 · 100BB · 앞선 레이즈 없음 · 오픈 레이즈 입문 예시</p><div class="content-tabs" style="margin-top:15px">${['CO','BTN','SB','BB'].map(pos=>`<button class="tab ${chartPos===pos?'active':''}" data-position="${pos}">${pos}</button>`).join('')}</div>${chartPos==='BB'?'<div class="feedback">BB는 앞선 액션에 대응하는 자리입니다. 아래 색상은 패의 상대적인 강도 참고용이며 BB 방어 범위가 아닙니다. 모두 콜했다면 체크도 가능합니다.</div>':''}<div class="chart-wrap"><div class="hand-chart" role="group" aria-label="시작 패 169종">${labels.flatMap((a,row)=>labels.map((b,col)=>{const pair=row===col,suited=row<col,ca=RANKS.indexOf(a),cb=RANKS.indexOf(b)+(suited?0:13),label=pair?a+b:(row<col?a+b:b+a)+(suited?'s':'o');return `<button class="chart-cell ${chartTier(ca,cb)} ${chartSelection===label?'selected':''}" data-hand="${label}" aria-label="${label}">${label}</button>`;})).join('')}</div></div><div class="chart-legend"><span><i class="legend-box strong"></i>강한 시작 패</span><span><i class="legend-box"></i>오픈 고려</span><span>어두움 · 폴드 우선</span></div><div class="feedback"><strong>${chartSelection}</strong>${chartSelection.endsWith('s')?'같은 무늬입니다. 플러시 가능성이 더해집니다.':chartSelection.endsWith('o')?'다른 무늬입니다. 높은 페어를 만들었을 때의 키커가 중요합니다.':'포켓 페어입니다. 높은 페어는 그 자체로 강하며 작은 페어는 보드에 더 민감합니다.'} ${chartPos}의 위치뿐 아니라 앞선 베팅과 상대, 스택을 함께 보세요.</div><p class="small muted" style="margin-top:16px;line-height:1.9">이 차트는 입문자를 위한 휴리스틱 예시입니다. GTO 차트가 아니며 토너먼트 숏스택이나 3벳 팟에는 그대로 적용할 수 없습니다. s = 같은 무늬 · o = 다른 무늬 · T = 10</p></div>`;}
function quizList(){return quizFilter==='missed'?QUESTIONS.filter(q=>progress.missed.includes(q.id)):quizFilter==='due'?dueQuestions(QUESTIONS,progress.answers):quizFilter.startsWith('topic:')?QUESTIONS.filter(q=>q.cat===quizFilter.slice(6)):QUESTIONS;}
function currentQuestion(){return QUESTIONS.find(q=>q.id===quizId)||quizList()[quizIndex%Math.max(1,quizList().length)];}
function trainHTML(){const q=currentQuestion();if(!q)return `${heading('DELIBERATE PRACTICE','복습을 모두 정리했어요.','반복해서 익힌 판단이 실전에서 힘이 됩니다.')}<div class="empty-state"><div class="empty-icon">✓</div><h2>지금 다시 풀 문제가 없습니다.</h2><p>맞힌 문제는 1·3·7·14일 간격으로 다시 만납니다. 전체 훈련도 언제든 열려 있어요.</p><button class="button primary" data-quiz-filter="all">전체 훈련 시작</button></div>`;
  const answered=quizAnswer!==null,ok=quizAnswer===q.answer;
  return `${heading('FIVE MINUTES, ONE BETTER DECISION','오늘의 한 수.','생각하고 선택하세요. 해설은 충분히 읽은 뒤 넘길 수 있습니다.',`<span class="pill gold">${Object.values(progress.answers).filter(a=>a.mastered).length} / ${QUESTIONS.length} 정답 경험</span>`)}<div class="quiz-container">${!quizSource?`<div class="content-tabs"><button class="tab ${quizFilter==='all'?'active':''}" data-quiz-filter="all">전체 훈련</button><button class="tab ${quizFilter==='missed'?'active':''}" data-quiz-filter="missed">오답 다시 풀기 · ${progress.missed.length}</button><button class="tab ${quizFilter==='due'?'active':''}" data-quiz-filter="due">오늘 복습 · ${dueQuestions(QUESTIONS,progress.answers).length}</button></div><div class="training-tools"><button class="text-button" data-do="daily-quiz">◇ 오늘의 공통 문제</button><button class="text-button" data-do="share-quiz">이 문제 공유 ↗</button>${quizFilter.startsWith('topic:')?`<span class="pill gold">${esc(quizFilter.slice(6))} 집중</span>`:''}</div>`:`<button class="text-button" data-lesson="${quizSource}">← 읽던 학습으로</button>`}<section class="quiz-card"><div class="quiz-top"><span>${q.cat.toUpperCase()} · 판단 훈련</span><span>${quizSource?'LESSON CHECK':String(quizIndex+1).padStart(2,'0')}</span></div>${q.cards||q.board?`<div class="quiz-context">${q.cards?`<div><small>내 카드</small><div class="card-row">${cardsHTML(parseCards(q.cards))}</div></div>`:''}${q.board?`<div><small>공용 카드</small><div class="card-row">${cardsHTML(parseCards(q.board))}</div></div>`:''}</div>`:''}<h2>${q.q}</h2><div class="quiz-choices">${q.choices.map((choice,i)=>`<button class="quiz-choice ${answered?(i===q.answer?'correct':i===quizAnswer?'wrong':''):''}" data-answer="${i}" ${answered?'disabled':''}><span class="letter">${answered&&i===q.answer?'✓':String.fromCharCode(65+i)}</span><span>${choice}</span></button>`).join('')}</div>${answered?`<div class="feedback" role="status"><strong>${ok?'잘 이해했습니다.':'이렇게 생각해 보세요.'}</strong>${q.why}${!ok?'<p style="margin-top:8px">오답 노트에 저장했습니다. 다시 맞히면 오답 목록에서 빠집니다.</p>':''}</div><div class="quiz-footer"><span>${ok?'이유까지 기억하면 내 실력이 됩니다.':'실수는 다음 판단을 위한 재료입니다.'}</span><button class="button primary" data-do="next-quiz">${quizSource&&ok?'학습 과정으로':'다음 문제'} →</button></div>`:'<p class="small muted" style="margin-top:19px">정답 하나를 고르세요. 시간 제한은 없습니다.</p>'}</section></div>`;
}
function reviewHTML(){const r=progress.history.find(h=>h.id===reviewId);if(r)return reviewDetailHTML(r);return `${heading('LOOK BACK. MOVE FORWARD.','내 선택을, 다시 보다.','당시의 정보로 돌아갑니다. 승패는 정답지가 아닙니다.',`<span class="pill">최근 ${progress.history.length}판</span>`)}${!progress.history.length?'<div class="empty-state"><div class="empty-icon">↺</div><h2>첫 복기는 첫 판 뒤에.</h2><p>카드와 행동, 그 순간의 코치 설명이 여기에 남습니다. 한 판을 시작해볼까요?</p><button class="button primary" data-nav="game">테이블로 이동 →</button></div>':`<div class="history-list">${progress.history.map(h=>`<button class="history-item" data-review="${h.id}"><div class="card-row">${cardsHTML(h.cards,{tiny:true})}</div><div class="history-info"><strong>${handLabel(h.cards)} · ${h.position} · ${h.folded?'폴드':h.showdown?'쇼다운':'상대 폴드'}</strong><small>${new Date(h.time).toLocaleString('ko-KR',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})} · 판단 ${h.notes.length}회 ${progress.reviewed.includes(h.id)?'· 복기 완료':''}</small></div><span class="net num ${h.net>=0?'positive':'negative'}">${h.net>0?'+':''}${fmt(h.net)}</span><span class="muted">→</span></button>`).join('')}</div>`}`;}
function reviewDetailHTML(r){return `<div class="reading"><button class="text-button" data-do="back-reviews">← 전체 복기</button>${heading('HAND REVIEW',`${handLabel(r.cards)} · ${r.position}`,'그때 무엇을 알고 있었는지, 선택의 이유를 봅니다.',`<span class="pill gold">${r.net>0?'+':''}${fmt(r.net)} 칩</span>`)}<div class="quiz-context"><div><small>내 카드</small><div class="card-row">${cardsHTML(r.cards)}</div></div><div><small>최종 보드 ${r.showdown?'':'· 공개된 카드만'}</small><div class="card-row">${cardsHTML(r.board)}</div></div></div><p class="small muted">코치 설명은 선택 전에 저장했습니다. 무작위 상대 기준 근사 분석이며, 선택마다 하나의 절대 정답이 있다는 뜻은 아닙니다.</p><div class="review-timeline">${r.notes.map((n,i)=>`<section class="review-step"><div class="step-head"><strong>${i+1}. ${streetKo[n.street]} · ${actionKo[n.action]}${n.amount?' '+fmt(n.amount):''}</strong><small>당시 팟 ${fmt(n.pot)}</small></div>${n.board.length?`<div class="card-row" style="margin:10px 0">${cardsHTML(n.board,{tiny:true})}</div>`:''}<p><span class="gold">검토할 선택: ${actionKo[n.advice.suggested]}</span><br>${esc(n.advice.why)}</p>${n.advice.equity!==null?`<p class="small muted" style="margin-top:8px">당시 추정 지분 ~${Math.round(n.advice.equity*100)}% · 콜에 필요한 지분 ${Math.round(n.advice.odds*100)}%</p>`:''}</section>`).join('')||'<div class="feedback">이번 판에는 내 자발적 행동 전에 승부가 끝났습니다. 아래 로그에서 흐름을 확인하세요.</div>'}</div><details><summary class="gold small">전체 행동과 팟 분배 보기</summary><div class="event-log">${r.events.map(e=>`<p class="${e.type==='street'?'street-event':''}">${esc(e.text)}</p>`).join('')}</div>${r.pots.map((p,i)=>`<p class="small muted" style="margin-bottom:7px">${i===0?'메인팟':'사이드팟 '+i} ${fmt(p.amount)} → ${p.awards.map(a=>`${r.names[a.player]} ${fmt(a.amount)}`).join(', ')}</p>`).join('')}</details><div class="feedback"><strong>나에게 묻는 세 가지</strong>왜 팟에 참여했나요?<br>상대는 어떤 패로 그 크기를 선택했을까요?<br>내 베팅은 더 약한 패에서 콜받거나, 더 강한 패를 접게 했나요?</div><div class="inline-actions" style="margin-top:20px"><button class="button ghost" data-do="export-review">복기 파일 저장</button><button class="button primary" data-do="mark-review">${progress.reviewed.includes(r.id)?'복기 완료 ✓':'복기 완료 · +15 XP'}</button></div></div>`;}
function growthHTML(){const b=belt(),solved=Object.values(progress.answers).filter(a=>a.mastered).length,attempts=Object.values(progress.answers).reduce((n,a)=>n+(a.attempts||0),0),correct=Object.values(progress.answers).reduce((n,a)=>n+(a.correct||0),0);const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return {label:d.getMonth()+1+'/'+d.getDate(),xp:progress.daily[key]?.xp||0};});const max=Math.max(20,...days.map(d=>d.xp));
  return `${heading('A LITTLE BETTER, EVERY DAY','실력은, 쌓이는 것.','플레이하고, 배우고, 돌아본 시간이 나의 기록이 됩니다.')}<section class="growth-hero"><div class="belt-symbol">♠</div><div class="grow-copy"><span class="eyebrow gold">LEVEL ${b.level}</span><h2>${b.name}</h2><p>${b.next?`다음 단계까지 ${fmt(b.next-progress.xp)} XP`:'배움에는 끝이 없습니다.'} · ${streak()}일 연속 학습</p><div class="progress-track"><span style="width:${b.pct}%"></span></div><span class="small gold">${fmt(progress.xp)} XP</span></div></section><div class="stat-grid">${[['완료한 핸드',fmt(progress.hands)],['정답 경험 문제',`${solved}/${QUESTIONS.length}`],['배운 과정',`${progress.lessons.length}/10`],['훈련 정답률',attempts?Math.round(correct/attempts*100)+'%':'—']].map(([label,val])=>`<div class="stat-tile"><span>${label}</span><b class="num">${val}</b></div>`).join('')}</div><div class="content-grid"><section class="info-card"><h3>최근 7일의 연습</h3><p class="small muted" style="margin-top:5px">학습과 플레이로 얻은 XP</p><div class="bar-chart">${days.map(d=>`<div class="bar-col"><small>${d.xp}</small><div class="bar" style="height:${Math.max(3,d.xp/max*72)}px"></div><small>${d.label}</small></div>`).join('')}</div></section>${missionsHTML()}</div><section class="info-card" style="margin-top:20px"><h3>나의 발자취</h3><div class="badge-grid">${[['♠','첫 번째 한 판','핸드 1판 완료',progress.hands>=1],['◎','원리 이해','서로 다른 5문제 정답',solved>=5],['↺','돌아보는 사람','복기 3판 완료',progress.reviewsCompleted>=3],['◇','꾸준한 연습','핸드 20판 완료',progress.hands>=20],['▤','도장 수료','학습 과정 10개 완료',progress.lessons.length>=10],['♜','도장 챔피언','챔피언십 우승',progress.trophies>0]].map(([icon,name,desc,done])=>`<div class="achievement ${done?'unlocked':''}"><div class="achievement-icon">${icon}</div><strong>${name} ${done?'✓':''}</strong><small>${desc}</small></div>`).join('')}</div></section>${weaknessHTML()}<p class="small muted" style="margin-top:18px;line-height:1.9">진행도와 최근 40판 복기는 이 기기의 브라우저에 저장됩니다. 설정에서 백업 파일을 저장하고 다른 기기로 가져올 수 있습니다. 다른 기기와 자동으로 동기화되지는 않습니다.</p>`;
}
function navigate(next){clearTimeout(timer);screen=next;raiseOpen=false;render();window.scrollTo({top:0,behavior:'instant'});schedule();}
function openDialog(title,html){clearTimeout(timer);dialogReturn=document.activeElement;$('dialog').innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${title}</h2><button class="dialog-close" data-do="close-dialog" aria-label="닫기">×</button></div>${html}`;if(!$('dialog').open)$('dialog').showModal();}
function closeDialog(){if($('dialog').open)$('dialog').close();}
$('dialog').addEventListener('close',()=>{if(dialogReturn?.isConnected)dialogReturn.focus();schedule();});
function settingsDialog(){openDialog('내 방식으로 연습하기',`<div class="form-row"><div><strong>코치 힌트</strong><small>코치 연습실에서만 표시합니다.</small></div><input type="checkbox" data-setting="hints" aria-label="코치 힌트" ${progress.settings.hints?'checked':''}></div><div class="form-row"><div><strong>효과음</strong><small>카드 · 칩 · 체크 · 내 차례 · 학습 완료</small></div><input type="checkbox" data-setting="sound" aria-label="효과음" ${progress.settings.sound?'checked':''}></div><div class="sound-controls"><label for="sound-volume">효과음 크기 <output id="sound-volume-value">${progress.settings.volume}%</output></label><input id="sound-volume" type="range" min="0" max="100" step="5" value="${progress.settings.volume}" aria-label="효과음 크기"><button class="button ghost" data-do="sound-preview">소리 들어보기 ♪</button><p class="small muted">배경음악 없이, 선택에 집중할 수 있는 짧은 소리만 재생합니다.</p></div><div class="form-row"><div><strong>네 가지 무늬 색상</strong><small>클럽 초록 · 다이아 파랑</small></div><input type="checkbox" data-setting="fourColor" aria-label="네 가지 무늬 색상" ${progress.settings.fourColor?'checked':''}></div><div class="form-row"><div><strong>진행 속도</strong><small>상대 행동을 확인하는 시간</small></div><select data-setting="speed" aria-label="진행 속도"><option value="slow" ${progress.settings.speed==='slow'?'selected':''}>천천히</option><option value="normal" ${progress.settings.speed==='normal'?'selected':''}>보통</option><option value="fast" ${progress.settings.speed==='fast'?'selected':''}>빠르게</option></select></div><div class="form-row"><div><strong>AI 난이도</strong><small>자기 카드와 공개 정보로 판단</small></div><select data-setting="difficulty" aria-label="AI 난이도"><option value="gentle" ${progress.settings.difficulty==='gentle'?'selected':''}>입문</option><option value="standard" ${progress.settings.difficulty==='standard'?'selected':''}>스탠다드</option></select></div><div class="inline-actions" style="margin-top:23px"><button class="button ghost" data-do="backup">진행도 백업</button><button class="button ghost" data-do="import">백업 가져오기</button>${hasRecovery()?'<button class="button ghost" data-do="undo-import">가져오기 전 기록 복원</button>':''}<input id="backup-file" type="file" accept=".json,application/json" hidden><button class="button ghost" data-do="install">홈 화면에 추가</button></div><button class="text-button" style="color:var(--red);margin-top:18px" data-do="reset-confirm">진행도 초기화</button><p class="small muted" style="margin-top:9px">현재 게임은 자동 저장됩니다. 학습 탭이나 설정을 열면 상대의 행동이 잠시 멈춥니다.</p>`);}
function modesDialog(){openDialog('오늘은 어떤 연습을 할까요?',`<p class="dialog-copy" style="margin-bottom:18px">${!table.s.over?'현재 진행 중인 판은 이어할 수 있도록 유지합니다. 테이블은 판을 끝낸 뒤 바꿀 수 있어요.':'모든 모드는 무료 가상 칩으로 플레이합니다. 기록과 학습 진도는 유지됩니다.'}</p><div class="mode-grid"><button class="mode-card" data-mode="practice" ${!table.s.over?'disabled':''}><strong>♠ &nbsp; 코치 연습실</strong><p>4인 테이블 · 100BB · 코치와 함께 차분하게</p><small>추천 · 칩을 모두 잃어도 자동으로 다시 연습</small></button><button class="mode-card" data-mode="tournament" ${!table.s.over?'disabled':''}><strong>♜ &nbsp; 도장 챔피언십</strong><p>6인 토너먼트 · 8판마다 블라인드 상승</p><small>힌트 없이 실전 도전 · 마지막 1명까지</small></button><button class="mode-card" data-mode="heads-up" ${!table.s.over?'disabled':''}><strong>◇ &nbsp; 헤즈업 스파링</strong><p>1:1 대결 · 포지션과 넓은 범위 판단</p><small>힌트 없이 직접 읽는 상대의 선택</small></button></div>${!table.s.over?'<button class="button wide" style="margin-top:15px" data-do="close-dialog">현재 판 이어하기 →</button>':''}`);}
function aboutDialog(){openDialog('한 판마다, 한 수 더.',`<div class="dialog-copy"><p>홀덤 도장은 승패를 넘어, 선택의 이유를 배우는 공간입니다. 카드 두 장에서 시작해 포지션, 확률, 상대의 범위까지 한 수씩 익힙니다.</p><div class="info-card" style="margin:20px 0"><span class="eyebrow gold">CREATED BY</span><h3 style="color:var(--ink);margin:8px 0">나상균</h3><a href="tel:01075295945" class="gold" style="font-size:21px;font-weight:600">010-7529-5945</a><p class="small" style="margin-bottom:0">게임 의견 · 문의 · 함께 만들어 갈 아이디어</p></div><p>모든 칩은 가상이며 결제·환전 기능이 없습니다. AI는 자기 카드와 공용 정보만 사용합니다. 코칭과 차트는 입문용 근사로, GTO 솔버 분석이나 보장된 승률이 아닙니다.</p><p>계정 없이 이용하며 기록은 이 기기의 브라우저에 저장됩니다. 게임은 외부 분석·광고 추적 코드를 사용하지 않습니다. 호스팅 제공자는 서비스 운영에 필요한 접속 정보를 처리할 수 있습니다.</p><p class="small"><a href="${location.protocol==='file:'?'https://holdem-brown.vercel.app/':'./'}privacy.html" target="_blank" rel="noopener">개인정보 및 기록 안내 ↗</a> · <a href="${location.protocol==='file:'?'https://holdem-brown.vercel.app/':'./'}guide.html" target="_blank" rel="noopener">홀덤 입문 가이드 ↗</a></p><p class="small">규칙 참고: <a href="https://www.pokertda.com/view-poker-tda-rules/" target="_blank" rel="noopener noreferrer">Poker TDA 베팅·쇼다운 규칙 ↗</a><br>HOLDEM DOJO · VERSION 3.1.0</p></div><button class="button primary wide" data-do="share">도장 링크 공유하기 ↗</button>`);}
function guideDialog(){openDialog('세 번의 선택으로 시작하세요.',`<p class="dialog-copy">개인 카드 2장과 공용 카드 5장 중 가장 강한 5장을 만드는 게임입니다. 내 차례가 되면 가능한 버튼이 켜집니다.</p><div class="onboarding-steps"><div><b>01</b><strong>내 카드 확인</strong><p>아래쪽 두 장이 내 카드입니다. 버튼 옆의 위치도 보세요.</p></div><div><b>02</b><strong>가격 보고 선택</strong><p>체크는 무료. 콜은 표시된 금액을 추가합니다.</p></div><div><b>03</b><strong>한 판 돌아보기</strong><p>결과와 관계없이 그 순간의 이유를 복기합니다.</p></div></div><p class="dialog-copy small">연습은 언제든 무료. 플레이 중 배우기 탭으로 이동하면 게임이 잠시 멈춥니다.</p><label class="welcome-sound"><input type="checkbox" data-setting="sound" ${progress.settings.sound?'checked':''}> 카드와 칩 효과음 켜기 <span class="muted">설정에서 언제든 조절</span></label><button class="button primary wide" style="margin-top:20px" data-do="start-guide">이제 테이블에 앉기 →</button>`);}
function start(mode='practice'){clearTimeout(timer);closeDialog();table=new Table({count:mode==='tournament'?6:mode==='heads-up'?2:4,mode});notes=[];screen='game';newHand();}
function newHand(){clearTimeout(timer);notes=[];coachCache=null;raiseOpen=false;if(table.start()){table.s.handId=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);sound('deal');save();render();schedule();}else{render();modesDialog();}}
function schedule(){clearTimeout(timer);if(!table||screen!=='game'||$('dialog').open||document.hidden||table.s.over||table.s.actor===0)return;const delay=progress.settings.speed==='fast'?180:progress.settings.speed==='slow'?1100:640;timer=setTimeout(()=>{try{if(screen!=='game'||$('dialog').open||document.hidden)return;if(table.s.actor<0){table.advance();sound('deal');}else{const actor=table.s.actor,move=decide(table.view(actor),Math.random,progress.settings.difficulty);table.act(actor,move.action,move.total);sound(move.action);}afterTransition();}catch(error){console.error(error);toast('게임 진행 중 문제가 생겼습니다. 저장된 판을 다시 확인해 주세요.');}},delay);}
function afterTransition(){coachCache=null;raiseOpen=false;if(table.s.over)recordFinished();else if(table.s.actor===0)sound('turn');save();render();schedule();}
function recordFinished(){const s=table.s;if(progress.history.some(h=>h.id===s.handId))return;const p=s.players[0],r=s.result;progress.hands++;daily().hands++;if(r.net[0]>0)progress.wins++;addXP(10);if(s.mode==='tournament'&&s.players.filter(p=>p.stack>0).length===1&&p.stack>0){progress.trophies++;addXP(100);sound('win');}else if(r.net[0]>0)sound('win');else sound('complete');progress.history.unshift({id:s.handId,time:Date.now(),number:s.handNumber,cards:[...p.cards],board:[...s.board],position:table.position(0),net:r.net[0],showdown:r.showdown,folded:p.folded,pots:structuredClone(r.pots),notes:structuredClone(notes),events:structuredClone(s.events),names:s.players.map(p=>p.name)});progress.history=progress.history.slice(0,40);progress.reviewed=progress.reviewed.filter(id=>progress.history.some(h=>h.id===id));}
function heroAction(action,total){if(table.s.actor!==0||table.s.over||$('dialog').open)return;const s=table.s,advice=coach();const note={street:s.street,board:[...s.board],pot:s.pot,action,advice:structuredClone(advice)};try{const result=table.act(0,action,total);note.amount=result.amount;notes.push(note);sound(action);afterTransition();}catch(error){toast('가능한 베팅 금액을 확인해 주세요.');console.error(error);}}
function setRaise(value){const legal=table.legal(0);const n=Math.round(Number(value));raiseAmount=Math.min(legal.maxRaise,Math.max(Math.min(legal.minRaise,legal.maxRaise),Number.isFinite(n)?n:legal.minRaise));if($('raise-range'))$('raise-range').value=raiseAmount;if($('raise-number'))$('raise-number').value=raiseAmount;const button=document.querySelector('[data-do="confirm-raise"]');if(button)button.textContent=`총 ${fmt(raiseAmount)}으로 확정`;}
function answerQuiz(choice){if(quizAnswer!==null)return;const q=currentQuestion();if(!q)return;quizAnswer=choice;const correct=choice===q.answer;const wasMastered=progress.answers[q.id]?.mastered;const a=updateRecall(progress.answers[q.id],correct);daily().questions++;if(correct){if(!wasMastered){addXP(25);toast('새로운 한 수를 익혔어요. +25 XP');}progress.missed=progress.missed.filter(id=>id!==q.id);sound('correct');if(quizSource&&!progress.lessons.includes(quizSource)){progress.lessons.push(quizSource);addXP(30);}}else{if(!progress.missed.includes(q.id))progress.missed.push(q.id);sound('retry');}progress.answers[q.id]=a;quizId=q.id;save();render();}
function download(name,data){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:typeof data==='string'?'text/plain;charset=utf-8':'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('파일 저장을 시작했습니다.');}
async function share(){const data={title:'홀덤 도장 — 한 판마다, 한 수 더.',text:'AI와 한 판, 코치와 복기. 무료로 홀덤을 배우는 나만의 도장.',url:'https://holdem-brown.vercel.app/'};try{if(navigator.share)await navigator.share(data);else if(navigator.clipboard){await navigator.clipboard.writeText(data.url);toast('도장 링크를 복사했습니다.');}else openDialog('도장 링크',`<p class="dialog-copy">아래 주소를 길게 눌러 복사하세요.</p><p class="gold" style="user-select:all">https://holdem-brown.vercel.app/</p>`);}catch(error){if(error.name!=='AbortError')toast('공유 메뉴를 열 수 없습니다. 주소창의 링크를 복사해 주세요.');}}
async function install(){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else openDialog('홈 화면에 도장 추가하기',`<div class="dialog-copy"><p><strong class="gold">iPhone · Safari</strong><br>공유 버튼 → ‘홈 화면에 추가’를 선택하세요.</p><p><strong class="gold">Android · Chrome</strong><br>메뉴(⋮) → ‘앱 설치’ 또는 ‘홈 화면에 추가’를 선택하세요.</p><p>설치 후 한 번 온라인으로 열면 캐시가 준비됩니다. 이후에는 오프라인에서도 게임과 학습을 이용할 수 있습니다.</p></div>`);}

function hasRecovery(){try{return !!localStorage.getItem(KEY+'-before-import');}catch{return false;}}
function weaknessHTML(){const topics=topicStats(QUESTIONS,progress.answers);return `<section class="info-card" style="margin-top:20px"><div class="card-top"><h3>어디를 더 연습할까요?</h3><button class="text-button" data-do="due-review">오늘 복습 ${dueQuestions(QUESTIONS,progress.answers).length}개 →</button></div><p class="small muted">풀어본 문제의 정답률입니다. 표본이 적으면 실력 평가보다 다음 연습의 참고로 보세요.</p><div class="topic-grid">${topics.map(t=>`<button class="topic-card" data-topic="${t.name}"><span>${t.name}</span><strong>${t.attempts?Math.round(t.correct/t.attempts*100)+'%':'시작 전'}</strong><small>${t.seen}/${t.total}문제 경험 · ${t.attempts}회 응답</small><div class="progress-track"><span style="width:${t.attempts?t.correct/t.attempts*100:0}%"></span></div></button>`).join('')}</div><p class="small muted">정답 뒤 1·3·7·14일 간격으로 재확인합니다. 틀린 문제는 오답 노트에서 즉시, 오늘 복습에서 10분 뒤 다시 풀 수 있어요.</p></section>`;}
async function shareQuiz(){const q=currentQuestion();if(!q)return;const url='https://holdem-brown.vercel.app/#quiz='+q.id;try{if(navigator.share)await navigator.share({title:'홀덤 도장 · 오늘의 한 수',text:q.q,url});else if(navigator.clipboard){await navigator.clipboard.writeText(url);toast('문제 링크를 복사했습니다.');}else openDialog('같은 문제 함께 풀기',`<p class="dialog-copy">${q.q}</p><p style="overflow-wrap:anywhere;user-select:all">${url}</p>`);}catch(e){if(e.name!=='AbortError')toast('주소를 공유하지 못했습니다. 잠시 뒤 다시 시도해 주세요.');}}
async function previewBackup(file){if(!file)return;try{if(file.size>5*1024*1024)throw Error('5MB 이하의 도장 백업을 선택해 주세요.');pendingBackup=readBackup(await file.text());const p=pendingBackup.progress;openDialog('이 기록을 가져올까요?',`<div class="dialog-copy"><p>${fmt(p.hands)}판 · ${p.lessons.length}개 과정 · ${fmt(p.xp)} XP<br>최근 복기 ${p.history.length}판</p><p>현재 기기의 기록을 이 백업으로 바꿉니다. 되돌릴 수 있도록 기존 기록도 기기에 한 번 보관합니다. 진행 중인 판은 이어지고, 완료된 판은 복기 목록에 남습니다.</p></div><div class="inline-actions"><button class="button ghost" data-do="close-dialog">취소</button><button class="button primary" data-do="restore-backup">이 기록 가져오기</button></div>`);}catch(e){pendingBackup=null;toast(e.message||'백업을 읽지 못했습니다.');}}
function restoreBackup(){if(!pendingBackup)return;const incoming=pendingBackup;try{const previous=localStorage.getItem(KEY);if(previous)localStorage.setItem(KEY+'-before-import',previous);localStorage.setItem(KEY,JSON.stringify(incoming));}catch{toast('저장 공간이 부족해 가져오지 못했습니다. 현재 기록은 유지됩니다.');return;}pendingBackup=null;progress={...defaults(),...incoming.progress,settings:{...defaults().settings,...incoming.progress.settings}};table=Table.restore(incoming.table);notes=incoming.notes;coachCache=null;quizId=null;quizAnswer=null;quizSource=null;quizFilter='all';reviewId=null;lessonId=null;closeDialog();screen='growth';if(table.s.over&&!table.s.result){table.start();table.s.handId=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);}audio.configure(progress.settings.sound,progress.settings.volume);save();render();toast('학습 기록을 가져왔습니다.');}
document.addEventListener('click',event=>{const el=event.target.closest('button');if(el?.dataset.topic){quizFilter='topic:'+el.dataset.topic;quizId=null;quizSource=null;quizAnswer=null;quizIndex=0;navigate('train');}if(el?.dataset.do==='due-review'){quizFilter='due';quizId=null;quizSource=null;quizAnswer=null;quizIndex=0;navigate('train');}});
window.addEventListener('hashchange',()=>{const q=new URLSearchParams(location.hash.slice(1)).get('quiz');if(QUESTIONS.some(x=>x.id===q)){quizId=q;quizAnswer=null;quizSource=null;navigate('train');}});

document.addEventListener('pointerdown',()=>audio.unlock(),{passive:true});
document.addEventListener('keydown',()=>audio.unlock());
document.addEventListener('click',event=>{
  const el=event.target.closest('button,a');if(!el||el.disabled)return;
  if(el.dataset.nav){event.preventDefault();navigate(el.dataset.nav);return;}
  if(el.dataset.action){heroAction(el.dataset.action);return;}
  if(el.dataset.lesson){closeDialog();lessonId=el.dataset.lesson;navigate('learn');return;}
  if(el.dataset.learnTab){learnTab=el.dataset.learnTab;lessonId=null;render();return;}
  if(el.dataset.position){chartPos=el.dataset.position;render();return;}
  if(el.dataset.hand){chartSelection=el.dataset.hand;const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-hand="${chartSelection}"]`)?.focus({preventScroll:true});return;}
  if(el.dataset.lessonQuiz){quizSource=el.dataset.lessonQuiz;quizId=LESSONS.find(l=>l.id===quizSource).quiz;quizAnswer=null;navigate('train');return;}
  if(el.dataset.quizFilter){quizFilter=el.dataset.quizFilter;quizIndex=0;quizId=null;quizSource=null;quizAnswer=null;render();return;}
  if(el.dataset.answer!=null){answerQuiz(Number(el.dataset.answer));return;}
  if(el.dataset.review){reviewId=el.dataset.review;navigate('review');return;}
  if(el.dataset.mode){if(table.s.over)start(el.dataset.mode);return;}
  if(el.dataset.size){const s=table.s,l=table.legal(0);setRaise(el.dataset.size==='all'?l.maxRaise:s.currentBet+Math.round((s.pot+l.call)*Number(el.dataset.size)));return;}
  switch(el.dataset.do){
    case 'raise':{const l=table.legal(0);if(!l.canRaise)break;raiseOpen=!raiseOpen;raiseAmount=Math.min(l.maxRaise,Math.max(l.minRaise,table.s.bb*3));render();if(raiseOpen)$('raise-range').focus();break;}
    case 'confirm-raise':heroAction('raise',raiseAmount);break;
    case 'next':if(table.s.over)newHand();break;
    case 'new-tournament':if(table.s.over)start('tournament');break;
    case 'sound':progress.settings.sound=!progress.settings.sound;audio.configure(progress.settings.sound,progress.settings.volume);audio.unlock();save();render();sound('chip');toast(progress.settings.sound?'효과음을 켰습니다.':'효과음을 껐습니다.');break;
    case 'settings':settingsDialog();break;
    case 'modes':modesDialog();break;
    case 'about':aboutDialog();break;
    case 'guide':guideDialog();break;
    case 'coach-detail':openDialog('지금 이 선택의 이유',coachHTML(coach(),true));break;
    case 'start-guide':progress.onboarded=true;audio.unlock();sound('deal');save();closeDialog();break;
    case 'close-dialog':closeDialog();break;
    case 'back-lessons':lessonId=null;render();break;
    case 'back-reviews':reviewId=null;render();break;
    case 'next-quiz':{const q=currentQuestion();if(quizSource&&quizAnswer===q.answer){lessonId=null;quizSource=null;quizId=null;quizAnswer=null;navigate('learn');}else if(quizSource){quizId=q.id;quizAnswer=null;render();}else{quizIndex++;quizId=null;quizAnswer=null;render();}break;}
    case 'mark-review':if(reviewId&&!progress.reviewed.includes(reviewId)){progress.reviewed.push(reviewId);progress.reviewsCompleted++;daily().reviews++;addXP(15);save();render();toast('선택을 돌아봤어요. +15 XP');}break;
    case 'export-review':{const r=progress.history.find(h=>h.id===reviewId);if(r)download(`holdem-review-${r.id}.json`,r);break;}
    case 'daily-quiz':quizSource=null;quizFilter='all';quizIndex=0;quizId=QUESTIONS[(Math.imul(Number(todayKey().replaceAll('-','')),2654435761)>>>0)%QUESTIONS.length].id;quizAnswer=null;render();break;
    case 'share-quiz':shareQuiz();break;
    case 'sound-preview':progress.settings.sound=true;audio.configure(true,progress.settings.volume);audio.unlock();{const toggle=document.querySelector('[data-setting="sound"]');if(toggle)toggle.checked=true;}save();render();setTimeout(()=>sound('deal'),40);setTimeout(()=>sound('raise'),360);setTimeout(()=>sound('turn'),700);break;
    case 'import':$('backup-file').click();break;
    case 'undo-import':try{const previous=JSON.parse(localStorage.getItem(KEY+'-before-import'));previewBackup(new File([JSON.stringify({version:3,...previous})],'before-import.json'));}catch{toast('이전 기록을 읽지 못했습니다.');}break;
    case 'restore-backup':restoreBackup();break;
    case 'backup':download(`holdem-dojo-backup-${todayKey()}.json`,{version:3,progress,table:table.s,notes});break;
    case 'log':openDialog('이번 판의 흐름',`<div class="event-log" style="max-height:55dvh">${table.s.events.map(e=>`<p class="${e.type==='street'?'street-event':''}">${esc(e.text)}</p>`).join('')}</div>`);break;
    case 'share':share();break;
    case 'install':install();break;
    case 'reset-confirm':openDialog('진행도를 초기화할까요?',`<p class="dialog-copy">이 브라우저의 레벨, 학습, 복기와 현재 게임을 지웁니다. 기록을 보관하려면 먼저 백업을 내려받으세요.</p><div class="inline-actions" style="margin-top:20px"><button class="button ghost" data-do="close-dialog">취소</button><button class="button primary" data-do="reset">초기화하기</button></div>`);break;
    case 'reset':try{localStorage.removeItem(KEY+'-before-import');}catch{}progress=defaults();audio.configure(progress.settings.sound,progress.settings.volume);progress.onboarded=true;notes=[];quizAnswer=null;quizId=null;reviewId=null;lessonId=null;start('practice');save();toast('새로운 도장을 시작합니다.');break;
  }
});
document.addEventListener('input',event=>{if(event.target.id==='sound-volume'){progress.settings.volume=Number(event.target.value);audio.configure(progress.settings.sound,progress.settings.volume);$('sound-volume-value').textContent=progress.settings.volume+'%';save();}if(event.target.dataset.lab){const key=event.target.dataset.lab;lab[key]=key==='stage'?event.target.value:Number(event.target.value);const output=document.getElementById('lab-'+key+'-value');if(output)output.textContent=fmt(lab[key]);document.querySelector('.lab-results').innerHTML=labResultHTML();}if(event.target.id==='raise-range')setRaise(event.target.value);if(event.target.id==='raise-number'){const n=Number(event.target.value);if(Number.isFinite(n))raiseAmount=Math.round(n);}});
document.addEventListener('change',event=>{if(event.target.id==='backup-file'){previewBackup(event.target.files?.[0]);return;}if(event.target.id==='sound-volume')sound('chip');if(event.target.id==='raise-number')setRaise(event.target.value);const key=event.target.dataset.setting;if(key){progress.settings[key]=event.target.type==='checkbox'?event.target.checked:event.target.value;audio.configure(progress.settings.sound,progress.settings.volume);audio.unlock();save();render();if(key==='sound')sound('chip');}});
document.addEventListener('keydown',event=>{if(event.repeat||event.ctrlKey||event.metaKey||event.altKey||/INPUT|SELECT|TEXTAREA/.test(event.target.tagName)||$('dialog').open||screen!=='game')return;const key=event.key.toLowerCase();if(key==='f'){event.preventDefault();heroAction('fold');}if(key==='c'){event.preventDefault();const l=table.legal(0);heroAction(l.call?'call':'check');}if(key==='r'){event.preventDefault();document.querySelector('[data-do="raise"]')?.click();}if(event.key==='Enter'&&raiseOpen){event.preventDefault();heroAction('raise',raiseAmount);}if(key==='n'&&table.s.over)newHand();});
document.addEventListener('visibilitychange',()=>{clearTimeout(timer);save();if(document.hidden)audio.pause();else{audio.unlock();schedule();}});
window.addEventListener('pagehide',save);
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
if('serviceWorker' in navigator&&location.protocol!=='file:'){window.addEventListener('load',()=>{navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{});});}
if(!table){table=new Table();table.start();table.s.handId=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);}else if(table.s.over&&!table.s.result){table.start();table.s.handId=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);}
if(table.s.over&&table.s.result&&!progress.history.some(h=>h.id===table.s.handId))recordFinished();
quizIndex=Math.max(0,QUESTIONS.findIndex(q=>!progress.answers[q.id]?.mastered));
const incomingQuiz=new URLSearchParams(location.hash.slice(1)).get('quiz');if(QUESTIONS.some(q=>q.id===incomingQuiz)){quizId=incomingQuiz;screen='train';}
daily();save();render();if(!progress.onboarded)guideDialog();else schedule();
if(storageWarning)setTimeout(()=>toast('현재 브라우저에서는 진행도 저장이 제한될 수 있습니다.'),600);
